internal class NVLeaveRequestAdditionalProcess
{
    LeaveBankTransaction    leaveBankTransaction;
    LeaveDate               transactionDate;
    LeaveTypeRecId          leaveType;
    HcmWorker               worker;

}

Method.Source:
public static NVLeaveRequestAdditionalProcess construct()
{
    return new NVLeaveRequestAdditionalProcess();
}

public void initBankTransaction(LeaveBankTransaction _leaveBankTransaction)
{
    leaveBankTransaction    = _leaveBankTransaction;
    leaveType               = _leaveBankTransaction.LeaveType;
    transactionDate         = _leaveBankTransaction.TransactionDate;
    worker                  = HcmWorker::find(_leaveBankTransaction.Worker);
}

public void process()
{      
    NVLeaveBalanceDetailsTmp detailsTmp = NVLeaveBalanceDetailsTmp::balanceByLeaveType(worker.RecId, transactionDate, leaveType);

    /// Request transaction only have one Amount
    /// We will check only first from deduct top with positive balance
    select firstonly detailsTmp
        order by detailsTmp.DeductPriority asc
        where detailsTmp.Balance > 0;

    ttsbegin;
    LeaveBankTransaction updateLeaveBankTransaction = LeaveBankTransaction::find(leaveBankTransaction.RecId, true);

    updateLeaveBankTransaction.NVLeaveCategory      = detailsTmp.Category;
    updateLeaveBankTransaction.NVTransactionYear    = detailsTmp.TransactionYear;

    updateLeaveBankTransaction.doUpdate();
    ttscommit;
}
